function [h_interp, s_interp, b_interp, u_interp] = init_steady_from_1Dwavg(md_x, md_y, mat_filename, sol_idx, bed2d)
    % InitializeISSMFrom1D Interpolates 1D python solutions onto ISSM mesh
    %
    % Inputs:
    %   md_x, md_y: Vectors of x and y coordinates from ISSM mesh (e.g. md.mesh.x)
    %   mat_filename: Path to the .mat file generated by python script
    %   sol_idx: Index of the solution to use (1-based index). Default is 1.
    %   bed2d: OPTIONAL md.geometry.bed. When supplied, the seed is applied
    %          y-AWARE (see below). When omitted or empty, the historical
    %          y-uniform behaviour is preserved exactly.
    %
    % Outputs:
    %   h_interp: Thickness interpolated on mesh
    %   s_interp: Surface interpolated on mesh
    %   b_interp: Bed interpolated on mesh
    %   u_interp: Velocity (x-component) interpolated on mesh
    %
    % WHY y-AWARE MATTERS (2026-07-28)
    % --------------------------------
    % A 1-D width-averaged solution is a function of x alone, so the historical
    % code interpolated it in x and applied the SAME thickness across the whole
    % width. On a laterally varying bed that is wrong in a specific, violent way.
    % The MISMIP+ bed adds By = dc*(...) up to +499.5 m at the flanks (dc=500,
    % wc=+/-24 km, fc=4 km). Grounded surface is bed + thickness, so a y-uniform
    % thickness reproduces that +499.5 m step in the SURFACE: an inverted
    % transverse dome, a 500 m ice ridge along both walls draining inward, when
    % the surface should be highest at the centreline. Measured on the MISMIP
    % seed: the flanks come out 28-36% too thick at every x.
    %
    % y-aware fix: preserve the 1-D SURFACE where the 1-D solution is grounded
    % and derive thickness from the real 2-D bed, h(x,y) = s_1d(x) - bed(x,y).
    % That drives the spurious transverse step to exactly zero. Downstream of
    % the 1-D grounding line the ice is floating, where the surface is set by
    % flotation rather than by the bed, so there the 1-D THICKNESS is what
    % must be preserved instead.
    %
    % NOTE: only `h_interp` survives in calc_steady_state.m -- it calls
    % ISSMModelUtils.adjust_thk_ols immediately afterwards, which recomputes
    % base/surface/ocean_levelset from the 2-D bed and the thickness. The
    % s_interp/b_interp returned here are the raw 1-D values, kept for callers
    % that want them.

    if nargin < 4 || isempty(sol_idx)
        sol_idx = 1;
    end
    if nargin < 5
        bed2d = [];
    end
    
    if ~isfile(mat_filename)
        error('File %s not found.', mat_filename);
    end
    
    data = load(mat_filename);
    
    % Handle cell array vs struct array structure from scipy.io.savemat
    if isfield(data, 'solutions')
        raw_sols = data.solutions;
        % Check if it is a cell array (common from python lists)
        if iscell(raw_sols)
            if sol_idx > length(raw_sols)
                error('Solution index %d out of range (found %d solutions).', sol_idx, length(raw_sols));
            end
            sol = raw_sols{sol_idx};
        else
            % Struct array
            if sol_idx > length(raw_sols)
                error('Solution index %d out of range (found %d solutions).', sol_idx, length(raw_sols));
            end
            sol = raw_sols(sol_idx);
        end
    else
        error('Variable ''solutions'' not found in .mat file.');
    end
    
    disp('Imported Solution:');
    sol
    % Extract 1D arrays
    % Note: Python arrays might come in as row or column vectors. 
    % We ensure they are column vectors for interp1.
    x_1d = double(sol.x(:));
    h_1d = double(sol.s(:) - sol.b(:));
    s_1d = double(sol.s(:));
    b_1d = double(sol.b(:));
    u_1d = double(sol.u(:));
    
    if isfield(sol, 'x_gl')
        x_gl = double(sol.x_gl);
    else
        x_gl = NaN;
    end
    
    % Interpolate onto ISSM mesh x-coordinates
    % We assume the solution is uniform in y (width-averaged)
    
    % Use 'linear' interpolation and 'extrap' to cover the whole domain
    h_interp = interp1(x_1d, h_1d, md_x, 'linear', 'extrap');
    s_interp = interp1(x_1d, s_1d, md_x, 'linear', 'extrap');
    b_interp = interp1(x_1d, b_1d, md_x, 'linear', 'extrap');
    u_interp = interp1(x_1d, u_1d, md_x, 'linear', 'extrap');
    
    % ---------------- y-aware correction (see header) ----------------
    if ~isempty(bed2d)
        bed2d = double(bed2d(:));
        if numel(bed2d) ~= numel(md_x)
            error(['init_steady_from_1Dwavg: bed2d has %d entries but the mesh ' ...
                   'has %d vertices.'], numel(bed2d), numel(md_x));
        end
        if ~isfinite(x_gl)
            error(['init_steady_from_1Dwavg: y-aware seeding needs the 1-D ' ...
                   'solution''s x_gl to tell grounded from floating, but the ' ...
                   '.mat file has no x_gl field.']);
        end

        h_uniform = h_interp;                 % what the old path would have used
        grounded  = md_x(:) <= x_gl;          % per the 1-D solution

        % Grounded: preserve the 1-D SURFACE against the true 2-D bed.
        h_grounded = s_interp(:) - bed2d;
        % Floating: preserve the 1-D THICKNESS (surface is set by flotation).
        h_interp = h_uniform(:);
        h_interp(grounded) = h_grounded(grounded);

        % A flank can stand above the 1-D surface; clamp rather than go negative.
        h_interp = max(h_interp, 0);
        h_interp = reshape(h_interp, size(md_x));

        fprintf('  y-AWARE seeding ON (bed supplied):\n');
        fprintf('    grounded vertices (x <= x_gl): %d of %d\n', ...
                sum(grounded), numel(md_x));
        d = h_interp(:) - h_uniform(:);
        fprintf('    thickness change vs y-uniform: min %+.1f m  max %+.1f m  mean %+.1f m\n', ...
                min(d), max(d), mean(d));
    else
        % Sanity check: Ensure thickness is non-negative
        h_interp(h_interp < 0) = 0;
    end

    fprintf('Initialized ISSM fields from 1D solution %d.\n', sol_idx);
    fprintf('  Grounding Line: %.2f km\n', x_gl/1000);
    fprintf('  Interpolated %d points.\n', length(md_x));
end
